import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.RequestChunkRadius{ChunkRadius: 12, MaxChunkRadius: 200}
RADIUS = bytes.fromhex("18c8")

# generated by gophertunnel b8bd735:
# &packet.RequestChunkRadius{ChunkRadius: -1, MaxChunkRadius: 255}
NEGATIVE_RADIUS = bytes.fromhex("01ff")

GOLDENS = [
    pytest.param(v2225.RequestChunkRadiusPacket(chunk_radius=12, max_chunk_radius=200), RADIUS, id="radius"),
    pytest.param(
        v2225.RequestChunkRadiusPacket(chunk_radius=-1, max_chunk_radius=255),
        NEGATIVE_RADIUS,
        id="negative-radius",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_request_chunk_radius_is_packet_69(version):
    assert version.packets[69] is version.RequestChunkRadiusPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_request_chunk_radius_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_request_chunk_radius_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_request_chunk_radius_rejects_a_body_carrying_only_the_radius():
    with pytest.raises(ValueError, match="at byte"):
        v2225.RequestChunkRadiusPacket.from_bytes(RADIUS[:1])
